/* Dashboard 2.0: Tabelleninhalt ueber alle fest reservierten Widgetzeilen spannen. */
.nrdb-ui-table > .v-table {
  grid-row: 1 / -1;
}

/* Leere optionale Felder behalten ein gut lesbares Label oberhalb des Rahmens. */
.nrdb-ui-form .v-field-label--floating {
  background: #ffffff;
  padding: 0 4px;
}

/* Lange Szenario-/Modellnamen auf schmalen Displays vollstaendig zeigen. */
@media (max-width: 600px) {
  .hmi-run-summary {
    grid-row-end: span 3 !important;
    grid-template-rows: repeat(3, var(--widget-row-height)) !important;
  }
  .hmi-run-summary .nrdb-ui-text-value {
    font-size: 14px;
    line-height: 1.25;
    overflow-wrap: anywhere;
    padding-inline: 6px;
  }
}

